/* Display and ticket rules only. Forecast fitting and weights are unchanged. */
(function(root){
'use strict';
const day=value=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value));
const half=value=>Number.isFinite(value)?Math.round(value*2)/2:null;
const decimal=odds=>Number.isFinite(odds)&&Math.abs(odds)>=100?(odds>0?1+odds/100:1+100/-odds):null;
const key=l=>[l.id,l.market||'moneyline',l.market==='total'?l.side:l.team,l.line??''].join(':');
const american=value=>value>1?(value>=2?'+'+Math.round((value-1)*100):String(-Math.round(100/(value-1)))):'—';
function dates(rows,now=Date.now()){
 const today=day(now),keys=[...new Set([today,...rows.map(g=>day(g.date))])].sort();
 return keys.filter(k=>k>=today).concat(keys.filter(k=>k<today).reverse());
}
function available(leg,now=Date.now()){
 if(!leg)return false;
 const age=now-Date.parse(leg.quoteAt),start=Date.parse(leg.date);
 return !!leg&&decimal(leg.odds)!==null&&Number.isFinite(start)&&start>now&&Number.isFinite(age)&&age>=0&&age<=72*3600000&&leg.timeValid===true&&!leg.reviewRequired;
}
function conflict(legs,leg){
 if(legs.length>=12)return 'Your betslip holds up to 12 picks.';
 if(legs.some(l=>l.id===leg.id))return 'Use one pick per game. For same-game picks, open Sniper Sauce.';
 if(legs.some(l=>[l.home,l.away].some(t=>[leg.home,leg.away].includes(t))))return 'This ticket already includes one of these teams.';
 if(legs.some(l=>l.provider!==leg.provider))return 'Keep all legs at the same sportsbook.';
 return null;
}
function ticketMath(legs,stake){
 const d=legs.length?legs.reduce((n,l)=>n*(decimal(l.odds)||0),1):0;
 const valid=Number.isFinite(stake)&&stake>0&&stake<=1000000&&d>1;
 return {decimal:d,odds:american(d),return:valid?stake*d:null,profit:valid?stake*(d-1):null,average:legs.length&&legs.every(l=>Number.isFinite(l.p))?legs.reduce((n,l)=>n+l.p,0)/legs.length:null,all:legs.length&&legs.every(l=>Number.isFinite(l.p))?legs.reduce((n,l)=>n*l.p,1):null};
}
function suggest(pool,count=2,now=Date.now()){
 if(!Number.isInteger(count)||count<1||count>12)return [];
 const eligible=pool.filter(l=>available(l,now)&&l.p>.5&&l.p-1/decimal(l.odds)>0).sort((a,b)=>b.p-a.p);
 let best=[],bestSum=-1;
 // Branch-and-bound avoids enumerating every 12-leg combination. The upper bound
 // ignores conflicts, so pruning cannot discard a better valid combination.
 for(const provider of new Set(eligible.map(l=>l.provider))){
  const rows=eligible.filter(l=>l.provider===provider);
  function visit(start,legs,sum){
   const need=count-legs.length;if(!need){if(sum>bestSum){best=legs;bestSum=sum;}return;}
   if(rows.length-start<need)return;
   if(sum+rows.slice(start,start+need).reduce((n,l)=>n+l.p,0)<=bestSum+1e-12)return;
   for(let i=start;i<=rows.length-need;i++)if(!conflict(legs,rows[i]))visit(i+1,[...legs,rows[i]],sum+rows[i].p);
  }
  visit(0,[],0);
 }
 return best;
}
function toggle(legs,leg){
 const selected=legs.findIndex(l=>key(l)===key(leg));
 if(selected>=0)return {legs:legs.filter((_,i)=>i!==selected),removed:true};
 const remaining=legs.filter(l=>!(l.id===leg.id&&l.market===leg.market)),error=conflict(remaining,leg);
 return error?{legs,error}:{legs:[...remaining,leg],removed:false};
}
function restoreDraft(value){
 if(!value||!Array.isArray(value.legs))return {legs:[],stake:10};
 const valid=restore([{id:'draft',stake:value.stake,legs:value.legs}]);
 return valid.length?{legs:valid[0].legs,stake:valid[0].stake}:{legs:[],stake:10};
}
function gradeLeg(leg,g){
 if(!g)return 'pending';
 if(/CANCELED|CANCELLED/.test(g.status||''))return 'void';
 if(!g.done)return 'pending';
 const hs=g.homeScore??g.hs,as=g.awayScore??g.as;
 if(!Number.isFinite(hs)||!Number.isFinite(as)||hs===as)return 'pending';
 if(leg.market==='moneyline')return (hs>as?g.home:g.away)===leg.team?'win':'loss';
 if(leg.market==='spread'){
  const margin=(leg.team===g.home?hs-as:as-hs)+leg.line;
  return Math.abs(margin)<1e-9?'push':margin>0?'win':'loss';
 }
 if(leg.market==='total'){
  const diff=hs+as-leg.line;return Math.abs(diff)<1e-9?'push':(diff>0)===(leg.side==='over')?'win':'loss';
 }
 return 'pending';
}
function settle(ticket,games){
 const legs=ticket.legs.map(l=>({...l,result:gradeLeg(l,games.find(g=>g.id===l.id))}));
 const result=legs.some(l=>l.result==='loss')?'loss':legs.some(l=>l.result==='pending')?'pending':legs.every(l=>['void','push'].includes(l.result))?'void':'win';
 const d=legs.filter(l=>l.result==='win').reduce((n,l)=>n*decimal(l.odds),1);
 const returned=result==='pending'?null:result==='loss'?0:ticket.stake*d;
 return {legs,result,returned,profit:returned===null?null:returned-ticket.stake};
}
function restore(value){
 if(!Array.isArray(value))return [];
 return value.filter(t=>t&&typeof t.id==='string'&&Number.isFinite(t.stake)&&t.stake>0&&t.stake<=1e6&&Array.isArray(t.legs)&&t.legs.length>0&&t.legs.length<=12&&t.legs.every(l=>l&&typeof l.id==='string'&&typeof l.team==='string'&&decimal(l.odds)&&(l.p===null||Number.isFinite(l.p)&&l.p>=0&&l.p<=1)&&(['moneyline','spread','total'].includes(l.market))&&(l.market==='moneyline'||Number.isFinite(l.line))&&(l.market!=='total'||['over','under'].includes(l.side)))).slice(0,100);
}
const api={key,day,half,decimal,american,dates,available,conflict,ticketMath,suggest,toggle,restoreDraft,gradeLeg,settle,restore};
root.GamedayEngine=api;if(typeof module!=='undefined')module.exports=api;
})(globalThis);

'use strict';
const Gameday=(()=>{
 const E=GamedayEngine,storeKey='darkhorse-tickets-v1',draftKey='darkhorse-betslip-v1';
 let slipTrigger=null;
 let selectedDay=E.day(Date.now()),started=[],legs=[],saved=[],lensId=null,ready=false,storageOK=true,stake=10,showArchived=false,toastTimer;
 const signed=n=>n>0?'+'+n:String(n),money=n=>n==null?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
 const fullDay=k=>new Date(k+'T12:00Z').toLocaleDateString('en-US',{timeZone:'UTC',weekday:'long',month:'long',day:'numeric'});
 function allRows(){
  const map=new Map(started.map(g=>[g.id,{...g,archived:true}]));
  for(const f of M.forecasts){const g=game(f);if(!map.has(g.id)){
   const row={...g,f};
   if(Date.parse(g.date)<=Date.now()&&Date.parse(M.generatedAt)<Date.parse(g.date)&&Date.parse(M.inputRetrievedAt)<Date.parse(g.date)){
    const m=meta(g),quoteOK=Date.parse(m.retrievedAt)<Date.parse(g.date);
    row.savedPick={homeMargin:f.coreMargin,total:f.coreTotal,forecastAt:M.generatedAt,quote:quoteOK?{homeSpread:m.homeSpread,overUnder:m.overUnder}:null};
   }
   map.set(g.id,row);
  }}
  for(const live of LiveScores.games){const row=map.get(live.id);if(row&&row.home===live.home&&row.away===live.away&&live.state!=='pre')map.set(live.id,{...row,...live});}
  return [...map.values()].sort((a,b)=>a.date.localeCompare(b.date));
 }
 function time(g){return g.timeValid===false?'Time TBA':new Date(g.date).toLocaleTimeString('en-US',{timeZone:'America/New_York',hour:'numeric',minute:'2-digit'});}
 function status(g){if(g.state==='in')return g.detail||'In progress';return g.done?'Final':/POSTPONED|CANCEL/.test(g.status||'')?StartedGames.state(g):Date.parse(g.date)<=Date.now()?'Started · score pending':time(g)+' ET';}
 function filtered(){const query=$('search').value.trim().toLowerCase(),conf=$('conference').value;return allRows().filter(g=>E.day(g.date)===selectedDay&&(conf==='all'||[g.home,g.away].some(t=>D.teams[t]?.conference===conf))&&(!query||[g.home,g.away].some(t=>[name(t),D.teams[t]?.abbr].some(v=>v?.toLowerCase().includes(query)))));}
 function quoteReady(o,g){return o&&o.state==='pre'&&!g.done&&Date.parse(g.date)>Date.now()&&E.available({odds:100,date:o.date,quoteAt:o.retrievedAt,timeValid:o.timeValid});}
 function pool(){
  if(typeof parlayOdds==='undefined'||!parlayOdds||DartHealth.health(M).stale)return [];
  const rows=[];
  for(const f of M.forecasts){const g=game(f),o=parlayOdds.games[g.id];if(!o||!quoteReady(o,g)||f.reviewRequired)continue;const q=forecast(f),base={id:g.id,home:g.home,away:g.away,provider:o.provider,date:o.date,quoteAt:o.retrievedAt,timeValid:o.timeValid,reviewRequired:f.reviewRequired,runId:M.refreshRunId,modelAt:M.inputRetrievedAt};
   for(const side of ['away','home']){const team=g[side],win=side==='home'?q.p:1-q.p,odds=o[side+'Moneyline'];if(E.decimal(odds))rows.push({...base,team,market:'moneyline',p:win,odds});const line=o[side+'Spread'],price=o[side+'SpreadOdds'];if(Number.isFinite(line)&&E.decimal(price))rows.push({...base,team,market:'spread',line,odds:price,p:null,modelPick:(side==='home'?q.margin:-q.margin)+line>0});}
   if(Number.isFinite(o.total))for(const side of ['over','under'])if(E.decimal(o[side+'Odds']))rows.push({...base,team:g.home,market:'total',side,line:o.total,odds:o[side+'Odds'],p:null,modelPick:side==='over'?q.total>o.total:q.total<o.total});
  }return rows;
 }
 function legFor(id,team,market='moneyline',side){return pool().find(l=>l.id===id&&l.market===market&&(market==='total'?l.side===side:l.team===team));}
 function freshLeg(l){return legFor(l.id,l.team,l.market,l.side);}
 function legLabel(l){return l.market==='total'?(l.side==='over'?'Over ':'Under ')+l.line:l.market==='spread'?name(l.team)+' '+signed(l.line):name(l.team)+' to win';}
 function marketButton(l){const selected=legs.some(x=>E.key(x)===E.key(l)),label=legLabel(l);return `<button class="gd-market-price gd-price ${l.modelPick?'gd-picked':''} ${selected?'gd-in-ticket':''}" data-add-game="${esc(l.id)}" data-add-team="${esc(l.team)}" data-market="${l.market}" data-side="${l.side||''}" aria-pressed="${selected}" aria-label="${esc('Add '+label+' at '+signed(l.odds))}"><span>${esc(label)}</span><b>${signed(l.odds)}</b>${l.modelPick?'<small>MODEL PICK</small>':''}</button>`;}
 function marketRows(g){const rows=pool().filter(l=>l.id===g.id&&l.market!=='moneyline');return `<div class="gd-market-board"><small>SPREAD</small><small>OVER / UNDER</small><div>${rows.filter(l=>l.market==='spread').map(marketButton).join('')||'<span>Prices unavailable</span>'}</div><div>${rows.filter(l=>l.market==='total').map(marketButton).join('')||'<span>Prices unavailable</span>'}</div></div>`;}
 function matchOdds(){if(!current||!ready)return;const g=game(current);let mount=$('gdMatchOdds');if(!mount){mount=document.createElement('div');mount.id='gdMatchOdds';$('marketInfo').after(mount);}const rows=pool().filter(l=>l.id===g.id);mount.innerHTML=rows.length?'<h3>Add to betslip</h3><div class="gd-match-moneylines">'+rows.filter(l=>l.market==='moneyline').map(l=>marketButton({...l,modelPick:l.p>.5})).join('')+'</div>'+marketRows(g):'';}
 function open(id){const f=M.forecasts.find(f=>f.id===id);if(!f){selectedDay=E.day(allRows().find(g=>g.id===id)?.date||Date.now());home();return;} $('matchConference').value='all';fillGames();show(id);tab('lab');document.querySelector('nav').scrollIntoView({behavior:'smooth',block:'start'});}
 function home(){tab('slate');document.querySelector('nav').scrollIntoView({behavior:'smooth',block:'start'});}
 function calendar(){
  const rows=allRows(),today=E.day(Date.now()),keys=E.dates(rows);
  if(!keys.includes(selectedDay))selectedDay=today;
  $('gdDates').innerHTML=keys.map(k=>{const d=new Date(k+'T12:00Z'),n=rows.filter(g=>E.day(g.date)===k).length;return `<button type="button" data-day="${k}" aria-pressed="${k===selectedDay}" class="gd-day ${k===selectedDay?'selected':''}"><small>${k===today?'TODAY':d.toLocaleDateString('en-US',{timeZone:'UTC',weekday:'short'}).toUpperCase()}</small><b>${d.getUTCDate()}</b><span>${d.toLocaleDateString('en-US',{timeZone:'UTC',month:'short'})} · ${n} games</span></button>`;}).join('');
  $('gdDayTitle').textContent=(selectedDay===today?'Today · ':'')+fullDay(selectedDay);
 }
 function ticker(){
  const today=E.day(Date.now()),rows=LiveScores.games.filter(g=>E.day(g.date)===today||g.state==='in').sort((a,b)=>(a.state==='in'?0:a.done?2:1)-(b.state==='in'?0:b.done?2:1)||a.date.localeCompare(b.date));
  const label=document.querySelector('.gd-ticker-label small');if(label)label.textContent=LiveScores.stale?(rows.length?'Scores delayed':'Connecting to scores'):'Refreshes every 10 min';
  $('gdTickerRail').innerHTML=rows.length?rows.map(g=>`<button class="gd-tick ${g.state==='in'?'gd-tick-live':''}" data-tick="${esc(g.id)}" aria-label="${esc(g.awayName+' at '+g.homeName+', '+(LiveScores.stale?'Score update delayed':g.detail))}"><span class="gd-tick-top">${LiveScores.stale?'DELAYED':g.state==='in'?'LIVE':g.done?'FINAL':'UPCOMING'}<em>${esc(g.state==='pre'?time(g)+' ET':g.detail)}</em></span>${['away','home'].map(side=>`<span class="gd-tick-team">${g[side+'Logo']?`<img src="${esc(g[side+'Logo'])}" alt="">`:''}<b>${esc(g[side+'Abbr']||g[side+'Name'])}</b><strong>${g[side+'Score']??'—'}</strong></span>`).join('')}<small>${g.state==='pre'?'Kickoff '+new Date(g.date).toLocaleDateString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric'}):LiveScores.stale?'Last received score':'Actual score'}</small></button>`).join(''):`<div class="gd-score-empty">${LiveScores.failed?'Scores unavailable. Retrying automatically.':LiveScores.retrievedAt?'No games scheduled today.':'Loading today’s scores…'}</div>`;
 }
 function tile(g){const upcoming=g.f&&Date.parse(g.date)>Date.now(),q=upcoming?forecast(g.f):null,m=meta(g),o=typeof parlayOdds==='undefined'?null:parlayOdds?.games[g.id],u=upcoming?upsetInfo(g.f):null,s=g.savedPick?StartedGames.selections(g):null;
  const readyQuote=upcoming&&Seabiscuit.eligibleQuote(o,g),active=upcoming&&!DartHealth.health(M).stale&&!g.f.reviewRequired;
  const pick=q?(q.margin===0?null:q.p>.5?g.home:g.away):s?.winner;
  const spread=q&&Number.isFinite(m.homeSpread)?(q.margin+m.homeSpread>0?g.home:g.away):s?.spread?.team;
  const total=q&&Number.isFinite(m.overUnder)&&q.total!==m.overUnder?(q.total>m.overUnder?'Over':'Under')+' '+m.overUnder:s?.total?s.total.side+' '+s.total.line:null;
  const sb=readyQuote&&u.market&&u.p>.5&&o[(u.home?'home':'away')+'Moneyline']>=170&&o[(u.home?'away':'home')+'Moneyline']<0&&active;
  return `<article class="gd-card ${sb?'gd-seabiscuit':''}"><div class="gd-card-head"><span>${esc(status(g))}</span><span>${esc((g.channels?.length?g.channels.join(' / '):channel(g)))}</span></div>${sb?'<div class="gd-sb-label">✦ SEABISCUIT PLAY</div>':''}<div class="gd-team-label"><span>${g.done?'Final':g.state==='in'?'Live score':upcoming?'Projected score':'Score pending'}</span><span>Moneyline</span></div>${['away','home'].map(side=>{const t=g[side],p=q?(side==='home'?q.p:1-q.p):null,price=readyQuote?o[side+'Moneyline']:null,score=g.done||g.state==='in'?(g[side+'Score']??g[side==='home'?'hs':'as']):q?(side==='home'?q.h:q.a):'—',r=g.f?.[side+'Profile']?.record,can=price!==null&&active;return `<div class="gd-team-row ${pick===t?'gd-team-picked':''}">${logo(t)}<div>${rankedName(t,!upcoming)}<small>${r?`${r.wins}–${r.n-r.wins} · `:''}${side==='home'&&!g.neutral?'Home':g.neutral?'Neutral':'Away'}${p!==null?' · '+pct(p)+' win chance':''}</small></div><strong>${score}</strong><button type="button" class="gd-price ${pick===t?'gd-picked':''}" data-add-game="${esc(g.id)}" data-add-team="${esc(t)}" ${can?'':'disabled'} aria-label="${esc(price!==null?'Add '+name(t)+' moneyline '+signed(price):name(t)+' moneyline unavailable')}">${price!==null?signed(price):'—'}${pick===t?'<small>MODEL PICK</small>':''}</button></div>`;}).join('')}<div class="gd-picks-row"><div><small>SPREAD PICK</small><b>${q&&Math.abs(q.margin+(m.homeSpread??0))<1e-9?'No lean':spread?esc(D.teams[spread]?.abbr||name(spread))+' '+signed(q?(spread===g.home?m.homeSpread:-m.homeSpread):s.spread.line):'Not posted'}</b></div><div><small>O/U PICK</small><b>${esc(total||'Not posted')}</b></div>${u?.market?`<div><small>${esc(D.teams[u.team]?.abbr||'UNDERDOG')} UPSET</small><b class="gd-mint">${pct(u.p)}</b></div>`:''}</div>${upcoming&&DartHealth.health(M).stale?'<p class="gd-warning">Picks paused · forecast refresh overdue.</p>':upcoming&&!readyQuote?'<p class="gd-muted">Moneyline unavailable · no ticket added.</p>':''}${active?marketRows(g):''}<div class="gd-card-footer">${upcoming?`<button data-open="${esc(g.id)}">Matchup ↗</button><button data-lens="${esc(g.id)}">Explore score ◉</button>`:`<a href="${esc(g.url)}" target="_blank" rel="noreferrer">Box score ↗</a>${s?'<span>Saved pregame picks</span>':'<span>No saved pregame pick</span>'}`}</div></article>`;
 }
 function lens(id){const f=M.forecasts.find(f=>f.id===id);if(!f)return;lensId=id;const g=game(f),q=forecast(f);$('gdLens').hidden=false;
  $('gdLens').innerHTML=`<div class="gd-panel-head"><div><span class="eyebrow">SCORE EXPLORER</span><h2>${esc(name(g.away))} <span>at</span> ${esc(name(g.home))}</h2></div><button data-close-lens aria-label="Close score explorer">×</button></div><div class="gd-lens-layout"><div class="gd-orbit"><svg viewBox="0 0 260 260" role="img" aria-label="Two team win chances"><circle class="gd-orbit-grid" cx="130" cy="130" r="117"/><circle class="gd-orbit-grid" cx="130" cy="130" r="91"/><circle class="gd-orbit-grid" cx="130" cy="130" r="66"/><path d="M0 130h260M130 0v260" class="gd-orbit-grid"/><circle class="gd-orbit-base" cx="130" cy="130" r="103"/><circle id="gdOrbitArc" cx="130" cy="130" r="103" pathLength="100" transform="rotate(-90 130 130)"/></svg><div class="gd-orbit-core"><small id="gdOrbitLabel"></small><strong id="gdOrbitPct"></strong><span>MODEL ESTIMATE</span></div></div><div class="gd-lens-controls"><div class="gd-lens-teams">${logo(g.away)}<b>${q.a} <span>–</span> ${q.h}</b>${logo(g.home)}</div><p class="gd-muted">Projected score</p><label for="gdMargin">Move the line. See how the chance changes.</label><input id="gdMargin" type="range" min="-35" max="35" step="0.5" value="0"><div class="gd-slider-labels"><span>${esc(D.teams[g.away].abbr)} by 35</span><span>${esc(D.teams[g.home].abbr)} by 35</span></div><h3 id="gdLensReadout" aria-live="polite"></h3><p class="gd-muted">Explores the forecast’s range. Does not change the pick.</p><button data-open="${esc(id)}" class="gd-primary">Full matchup ↗</button></div></div>`;
  const update=()=>{const n=Number($('gdMargin').value),p=n<0?cdf((n-q.margin)/f.coreSd):1-cdf((n-q.margin)/f.coreSd),team=n<0?g.away:g.home;$('gdOrbitArc').style.strokeDasharray=`${p*100} 100`;$('gdOrbitLabel').textContent=D.teams[team]?.abbr||name(team);$('gdOrbitPct').textContent=pct(p);$('gdLensReadout').textContent=`${pct(p)} chance ${name(team)} ${n===0?'wins outright':'wins by more than '+Math.abs(n)+' points'}.`;};$('gdMargin').oninput=update;update();$('gdLens').scrollIntoView({behavior:'smooth',block:'start'});
 }
 function render(){if(!ready)return;calendar();ticker();const rows=filtered();
  const sort=$('gdSort').value;if(sort==='upset')rows.sort((a,b)=>(b.f?upsetInfo(b.f).p||0:0)-(a.f?upsetInfo(a.f).p||0:0));
  $('gdCount').textContent=rows.length+' games';$('gdGrid').innerHTML=rows.length?rows.map(tile).join(''):'<div class="gd-empty"><h3>No games here.</h3><p>Choose another date or clear your team and conference filters.</p></div>';
  const fs=rows.filter(g=>g.f&&Date.parse(g.date)>Date.now()).map(g=>g.f);Seabiscuit.renderHub(fs);const upset=$('seabiscuitHub');if(upset)$('gdUpsets').append(upset);
  $('gdUpsets').hidden=!fs.length;
  $('gdQuoteNote').textContent='Odds are saved quotes, not live prices. Tap odds to add a pick. All times Eastern.';
  matchOdds();renderBuilder();
 }
 function notice(text){$('gdTicketStatus').textContent=text;const toast=$('gdToast');if(toast){$('gdToastText').textContent=text;toast.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.hidden=true,6500);}}
 function persistDraft(){try{localStorage.setItem(draftKey,JSON.stringify({legs,stake}));}catch(e){notice('Betslip cannot save on this browser. Download a copy.');}}
 function openSlip(){slipTrigger=document.activeElement;$('gdSlip').hidden=false;$('gdSlipBackdrop').hidden=false;document.body.classList.add('gd-slip-open');$('gdCloseSlip').focus();}
 function closeSlip(){ $('gdSlip').hidden=true;$('gdSlipBackdrop').hidden=true;document.body.classList.remove('gd-slip-open');if(slipTrigger?.isConnected)slipTrigger.focus();}
 function add(id,team,market='moneyline',side){
  const selected=legs.find(l=>l.id===id&&l.market===market&&(market==='total'?l.side===side:l.team===team)),l=selected||legFor(id,team,market,side);
  if(!l||(!selected&&(!E.available(l)||DartHealth.health(M).stale))){notice('This pick is unavailable or has already started.');return;}
  const next=E.toggle(legs,l);if(next.error){notice(next.error);return;}
  legs=next.legs;persistDraft();renderBuilder();notice(legLabel(l)+(next.removed?' removed from betslip.':' added to betslip.'));
 }
