  return [start,kickoff,stamp].every(Number.isFinite)&&Math.min(start,kickoff)>now&&stamp<=now&&now-stamp<=maxQuoteAge&&['homeMoneyline','awayMoneyline'].every(k=>Number.isFinite(o[k])&&Math.abs(o[k])>=100);
 }
