  const favorites=pool.filter(r=>r.odds<0&&r.p>=.65).sort((a,b)=>b.p-a.p).slice(0,8),dogs=pool.filter(r=>r.odds>0&&r.p>.5).sort((a,b)=>b.p-a.p).slice(0,8);
