}
function pCard(t,i){const single=t.legs.length===1;return `<article class="ticket"><div class="ticket-top"><span>${single?'SINGLE PICK':t.legs.length+'-LEG PARLAY'} · ${esc(t.legs[0].o.provider)}</span><b>#${i+1}</b></div><div class="ticket-pay"><strong>${pAmerican(t.decimal)}</strong><span>${single?'Quoted moneyline':'Calculated combined odds'}</span></div><div class="ticket-metrics"><div><b>${pPercent(t.p)}</b><small>${single?'Model win chance':'Estimated all-legs hit chance*'}</small></div><div><b>$${(10*t.decimal).toFixed(2)}</b><small>Total return on $10 · includes stake</small></div></div><div class="ticket-risk">${pPercent(1-t.p)} estimated chance of losing${single?'':' at least one leg'}.</div><div class="ticket-legs">${t.legs.map(r=>`<div class="ticket-leg"><div class="ticket-team">${logo(r.team)}<div><b>${rankedName(r.team)}</b><small>TO WIN · ${r.odds>0?'+':''}${r.odds}</small></div><span>${pPercent(r.p)}</span></div><p class="ticket-match">${rankedMatchup(r.g)}<br>${esc(new Date(r.o.date).toLocaleString('en-US',{timeZone:'America/New_York',weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}))} ET · ${esc(r.o.channels.length?r.o.channels.join(' / '):channel(r.g))}</p><p>${esc(pReason(r))}</p><button class="ticket-report" data-pmatch="${esc(r.id)}">Matchup report ↗</button><details><summary>Price & source</summary><p>Break-even at this price: ${pPercent(1/r.decimal)}. Model: ${pPercent(r.p)}. Difference: ${(r.edge*100).toFixed(1)} percentage points. This comparison does not establish a betting edge.</p><p>Retrieved ${esc(new Date(r.o.retrievedAt).toLocaleString('en-US',{timeZone:'America/New_York'}))} ET. <a href="${esc(r.o.url)}" target="_blank" rel="noreferrer">ESPN game source ↗</a></p></details></div>`).join('')}</div><div class="ticket-bottom"><span>Profit if it wins: <b>$${(10*(t.decimal-1)).toFixed(2)}</b></span><button data-add-parlay="${i}" class="ticket-save">Add to betslip +</button><button data-pticket="${i}" class="ticket-save">Download ↓</button></div></article>`}
function pRender(){
 const week=$('parlayWeek').value,pool=pCandidates(week),cat=parlayCategories.find(c=>c.id===parlayCategory);
 parlayTickets=pBuild(parlayCategory,pool);
 Seabiscuit.renderWeek(week,pool);
 $('parlayCats').innerHTML=parlayCategories.map(c=>`<button aria-pressed="${c.id===parlayCategory}" class="${c.id===parlayCategory?'selected':''}" data-pcategory="${c.id}"><span>${c.icon} / ${c.tag}</span><b>${c.name}</b></button>`).join('');
