 $('parlayCards').innerHTML=parlayTickets.length?parlayTickets.map(pCard).join(''):'<article class="parlay-empty"><h3>No qualifying tickets yet.</h3><p>Try another category or week. Games need a current model, a known kickoff, current moneylines and no unresolved reported QB availability concern. We won’t fill a ticket with unavailable odds.</p></article>';
